217	    @ExceptionHandler(OwnerCityFullException.class)
218	    @ResponseBody
219	    public ResponseEntity<ProblemDetail> handleOwnerCityFullException(OwnerCityFullException e, HttpServletRequest request) {
220	        logger.debug("Owner city at capacity at {} {}: {}",
