15	    private LocalityResolver() {
16	    }
17	
18	    /**
19	     * Returns the canonical region for the given city (Sydney-&gt;NSW,
20	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD), or "UNKNOWN" when the city is not in
21	     * the table (including a {@code null} city).
